with open("prd.json", encoding="utf-8") as f:
    prd = json.load(f)

existing_ids = {s["id"] for s in prd["userStories"]}
new_to_add = [s for s in NEW_STORIES if s["id"] not in existing_ids]
print(f"Existing: {len(prd['userStories'])}, Adding: {len(new_to_add)}")
prd["userStories"].extend(new_to_add)

with open("prd.json", "w", encoding="utf-8") as f:
    json.dump(prd, f, indent=2, ensure_ascii=False)

total = len(prd["userStories"])
pending = sum(1 for s in prd["userStories"] if not s.get("passes") and not s.get("_skipped"))
